class Solution {
    public String convertToBase7(int num) {
        if (num == 0) return "0";
        boolean neg = num < 0;
        long n = Math.abs((long)num);
        StringBuilder sb = new StringBuilder();
        while (n > 0) {
            sb.append(n % 7);
            n /= 7;
        }
        if (neg) sb.append('-');
        return sb.reverse().toString();
    }
}

var convertToBase7 = function(num) {
    if (num === 0) return "0";
    const neg = num < 0;
    let n = Math.abs(num);
    const res = [];
    while (n > 0) {
        res.push(String(n % 7));
        n = Math.floor(n / 7);
    }
    if (neg) res.push("-");
    return res.reverse().join('');
};
